"""Real backup fixture generated by official Duplicati 2.4.0.1 CLI."""
import hashlib
import tempfile
import unittest
from pathlib import Path
from duplicati_db import DuplicatiDB
from reader import Backup

FIXTURE=Path(__file__).parent/'fixtures'/'real'
EXPECTED=b'Duplicati real backup fixture 2026\n'


class RealBackupTests(unittest.TestCase):
    def test_real_zip_index_and_restore(self):
        with tempfile.TemporaryDirectory() as tmp:
            catalog=Path(tmp)/"catalog.sqlite"
            db=Backup(FIXTURE/"backup",catalog)
            try:
                self.assertEqual(db.index()["versions_added"],1)
                version=db.snapshots()[0]["id"]
                file=next(p for p in db.list(version) if p["path"].endswith("/example.txt"))
                output=db.restore_file(version,file["path"],tmp)
                self.assertEqual(Path(output).read_bytes(), EXPECTED)
            finally:
                db.close()

    def test_real_database_restore(self):
        db=DuplicatiDB(FIXTURE/'backup', FIXTURE/'job.sqlite')
        try:
            versions=db.snapshots()
            self.assertEqual(len(versions), 1)
            paths=db.list(versions[0]['id'])
            file=next(p for p in paths if p['path'].endswith('/example.txt'))
            with tempfile.TemporaryDirectory() as out:
                target=Path(db.restore_file(versions[0]['id'], file['path'], out))
                self.assertEqual(target.read_bytes(),EXPECTED)
        finally:
            db.close()


if __name__=='__main__':
    unittest.main()
